const read = (at: string, calls: number, input: number, output: number, status = 'ok'): LastReading => (
  { at, status, model: 'claude-sonnet-5-5', calls, input_tokens: input, output_tokens: output });

/** One overview row: [carrier, sha, stored, number, pages], its split, its pull, its reading, [live, questions, not placed]. */
function row(
  n: number, [carrier, file_sha256, stored_at, bulletin_number, pages]: [string, string, string, string, number],
  split: Partial<Record<'settled' | 'answered' | 'read' | 'unread' | 'waiting', number>>, outcome: string, last_reading: LastReading | null,
  [requirements_live, questions_open, not_placed]: [number, number, number], pulledAt = OCT_20_SWEEP,
): OverviewRow {
  return {
    carrier, bulletin_id: id(n), bulletin_number, file_sha256, stored_at, pages, settled: 0, answered: 0, read: 0, unread: 0, waiting: 0, ...split,
    last_pull: { at: pulledAt, outcome }, last_reading, requirements_live, questions_open, not_placed,
  };
}

