/** Counts in VERDICT_ORDER: [requirements, unsettled, corrected, not on page, duplicate, confirmed]. */
type Found = [number, number, number, number, number, number];

/** A file's pages: each in its part, its state, read on this file when `fresh` holds it, else carried from the June file. */
function pagesOf(count: number, parts: [number, string][], state: (page: number) => PageState, fresh: number[], found: Record<number, Found>): BulletinPage[] {
  return Array.from({ length: count }, (_, index) => {
    const page = index + 1;
    const at = parts.findIndex(([from]) => from === page);
    const part = at > 0 ? `${parts[at - 1][1]} | ${parts[at][1]}` : ([...parts].reverse().find(([from]) => from <= page)?.[1] ?? '');
    const pageState = state(page);
    const answered = pageState === 'settled' || pageState === 'read';
    const [requirements, unsettled, corrected, not_on_page, duplicate, confirmed] = found[page] ?? [answered ? (page * 7) % 4 : 0, 0, 0, 0, 0, 0];
    return {
      page, part, state: pageState, read_at: answered ? '2026-10-22T01:24:00Z' : null, read_from: answered && !fresh.includes(page) ? JUNE_FILE : null,
      requirements, verdicts: { confirmed, corrected, duplicate, not_on_page, unsettled },
    };
  });
}

