const SF_13_IMAGE = 'data:image/png;base64,';

/** One read of the lane as the view root holds it: the answer, null until it lands, and why none came. */
type FakeRead<T> = { value: T | null; trouble: AffectedAreasTrouble | null };
const answered = <T>(value: T | null): FakeRead<T> => ({ value, trouble: null });

/**
 * The four reads the view root draws until the fill's hooks replace them: the thirteen carriers, a bulletin's pages, a
 * page's reading and its image. A bulletin or page the fake holds nothing for reads as still loading.
 */
export const FAKE_READS = {
  overview: answered(OVERVIEW),
  pages: (bulletinId: string | null): FakeRead<BulletinPage[]> => answered(bulletinId === null ? null : PAGES[bulletinId] ?? null),
  reading: (bulletinId: string | null, page: number | null): FakeRead<PageReading> => answered(page === null ? null : READINGS[`${bulletinId}:${page}`] ?? null),
  image: (sha: string | null, page: number | null): string | null => (sha === SF_SHA && page === 13 ? SF_13_IMAGE : null),
};
